entries[82765] = { ["name"] = "Zügel der grünen Drachenschildkröte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört eine reitbare grüne Drachenschildkröte oder gibt sie wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Sie werden geschätzt, weil sie viel tragen können und einen sicheren Schritt haben. Deshalb sind diese robusten Tiere die erste Wahl vieler Pandaren.\"\nVerkäufer:\nSchildkrötenmeisterin Odai\nZone:\nOrgrimmar\nKosten:\n\nVerkäufer:\nDer alte Weißnase\nZone:\nSturmwind\nKosten:" }
