entries[83075] = { ["name"] = "Saftfliegenteile", ["text"] = "Questgegenstand\n\"Flügel, Thoraxe, Augen und andere Teile. Sie leuchten schwach bernsteinfarben.\"" }
entries[83076] = { ["name"] = "Der Biss in den Saurokapfel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Dies ist ein Sendschreiben von den Lehrensuchern im Tal der Ewigen Blüten. Sie interessieren sich für Eure Forschung bezüglich der Saurok.\"" }
entries[83078] = { ["name"] = "Das Erbe der Meister (Teil 1)", ["text"] = "Einzigartig\n\"Dieses leicht angesengte Sendschreiben enthält das Protokoll eines kürzlich abgehaltenen Treffens.\"\n<Zum Lesen rechtsklicken>" }
entries[83079] = { ["name"] = "Wappenrock der Tushui", ["text"] = "Wird beim Aufheben gebunden\nWappenrock\nAnlegen: Ihr tragt die Insignien der Tushui-Pandaren. Jeglicher Rufzuwachs in Dungeons kommt Eurem Ansehen bei ihnen zugute." }
entries[83080] = { ["name"] = "Wappenrock der Huojin", ["text"] = "Wird beim Aufheben gebunden\nWappenrock\nAnlegen: Ihr tragt die Insignien der Huojin-Pandaren. Jeglicher Rufzuwachs in Dungeons kommt Eurem Ansehen bei ihnen zugute." }
entries[83086] = { ["name"] = "Herz der Obsidiannachtschwinge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man sich in eine Obsidiannachtschwinge verwandelt. In verwandelter Form könnt Ihr einen Verbündeten auf dem Rücken tragen. Das ist ein Flugreittier.\nVerwandelt Euch in eine Obsidiannachtschwinge, wodurch Ihr sehr schnell fliegen und einen Verbündeten auf Eurem Rücken tragen könnt. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Wenn man nicht mehr rennen kann, kriecht man halt, und wenn man nicht mehr kriechen kann, sucht man sich jemanden, der einen trägt.\"\nWerbt einen Freund" }
entries[83087] = { ["name"] = "Rubinpanther", ["text"] = "Reittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier fliegt oder läuft in Abhängigkeit von Eurer Reitfertigkeit und Eurem Aufenthaltsort.\nBeschwört einen reitbaren Rubinpanther oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Legenden zufolge hat ein uralter pandarischer Kaiser den ersten juwelenbesetzten Panther für seinen Sohn gefertigt, nachdem dessen Zwillingsbruder einer Krankheit erlag.\"\nBeruf:\nJuwelierskunst" }
