entries[83094] = { ["name"] = "Footes Dreifachgebrannter", ["text"] = "Benutzen: Ein starkes alkoholisches Getränk.\n\"Überraschend stark.\"\nVerkaufspreis:" }
entries[83095] = { ["name"] = "Lagrave Bock", ["text"] = "Benutzen: Ein ziemlich schwaches alkoholisches Getränk.\n\"Der dunkle, vollmundige Geschmack erinnert leicht an getrocknete Früchte und Schokolade.\"\nVerkaufspreis:" }
entries[83096] = { ["name"] = "Ausgebrannte Glyphe", ["text"] = "Klassen: Krieger\n\"Es sieht zwar aus, als wäre diese Glyphe entsetzlich verbrannt und hätte jegliche Magie verloren, doch ein Händler bemerkt den Unterschied vielleicht nicht...\"\nVerkaufspreis:" }
entries[83097] = { ["name"] = "Schildkrötendörrfleisch", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 1128 * 20 / 5) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Zäh und fleischig.\"\nVerkaufspreis:" }
