entries[83124] = { ["name"] = "Becher voll Dschungelbräu", ["text"] = "Questgegenstand\n\"Dieser dampfende Krug hat vielfältige Gerüche und Geschmäcker.\"" }
entries[83128] = { ["name"] = "Bräuverteidigerkugel", ["text"] = "Unga Ingu\nEinzigartig\nDauer: 10 min (Realzeit)\nBenutzen: Verwandelt Euch 10 Min. lang in ein Pandajunges." }
